-- The Probationary Roster (4 aspirants, parsed from app.js)
INSERT OR IGNORE INTO members (name, slug, status, region, sponsor, recognized_date, standing_since, photo, notes, on_public_site) VALUES ('Mr. Payton Marki', 'mr-payton-marki', 'Secret Probationary', 'Originally of Missouri, presently of Milwaukee', 'Mr. Matt Lange', '2023', '2023-01-01', 'bwpayton.jpg', 'Mr. Marki has been a pledge of this Society since 2023, and the Commodore wishes it understood that this is not an oversight. It has been open to him to press his case at any hour of any of those three years. He has not pressed it. He appears, so far as anyone has been able to establish, to be entirely content. The membership has turned this over at length and remains unable to account for it, and the Commodore has stopped pretending he can. Mr. Marki is to be married upon the tenth of October, which may go some distance toward explaining the preoccupation. It does not excuse it.', 1);
INSERT OR IGNORE INTO members (name, slug, status, region, sponsor, recognized_date, standing_since, photo, notes, on_public_site) VALUES ('Mr. Thomas Kavanagh', 'mr-thomas-kavanagh', 'Double Secret Probationary', 'Of Columbus, Ohio — some 640 miles distant', NULL, '2020', '2020-01-01', '/images/thomas-kavanagh.jpg', 'Mr. Kavanagh gave his word upon the instant the question was put to him, and this Society admired the performance greatly at the time. He has since attended nothing. The Commodore continues to hold the word in the highest regard and has begun quietly to hope that it might one day arrive accompanied by the man.', 1);
INSERT OR IGNORE INTO members (name, slug, status, region, sponsor, recognized_date, standing_since, photo, notes, on_public_site) VALUES ('Mr. John Kavanagh', 'mr-john-kavanagh', 'Double Secret Probationary', 'Of Columbus, Ohio — some 640 miles distant', NULL, '2020', '2020-01-01', '/images/john-kavanagh.jpg', 'Mr. Kavanagh pronounced his brother’s pledge to be smoke, said so to his brother’s face, and was proven entirely correct — a vindication somewhat undercut by his own absence on the very same afternoon. The Society has entered the prediction as sound. The Society has entered the predictor’s whereabouts separately.', 1);
INSERT OR IGNORE INTO members (name, slug, status, region, sponsor, recognized_date, standing_since, photo, notes, on_public_site) VALUES ('Mr. Paul Kavanagh', 'mr-paul-kavanagh', 'Probationary', 'Of Columbus, Ohio · father to Thomas and John', NULL, '2026', '2026-09-05', NULL, 'Mr. Kavanagh regarded an arithmetic that had defeated this Society for six years and proposed, without ceremony, that we should simply drive to him. The Commodore has reviewed the proposal at length and been unable to locate the flaw in it, which is not a sensation this office is accustomed to. That it fell to the father to arrange what the sons could not has been noted, and shall go on being noted.', 1);

